"""Extract actual texture creation/destruction code for a mocked-transport test."""
import argparse
import re
from pathlib import Path
try:
    from .native_source import function, function_bounds
except ImportError:
    from native_source import function, function_bounds


KINDS = ("Volume", "Cube")


def prepare(source, output, negative_control=None):
    client = source / "bridge/src/client"
    device = (client / "d3d9_device.cpp").read_text(encoding="utf-8")
    notices = device[:device.index('#include "pch.h"')]
    methods = []
    wrappers = []
    for kind in KINDS:
        name = f"Direct3D{kind}Texture9_LSS"
        stem = f"d3d9_{kind.lower()}texture"
        header = (client / f"{stem}.h").read_text(encoding="utf-8")
        implementation = (client / f"{stem}.cpp").read_text(encoding="utf-8")
        fields = re.findall(r"^  bool m_serverCreated = [^;]+;", header, re.MULTILINE)
        cancellations = re.findall(r"^  void cancelServerCreation\(\) \{[^\n]+\}", header, re.MULTILINE)
        if len(fields) != 1 or len(cancellations) != 1:
            raise ValueError(f"Creation state changed in {stem}; update the harness")
        wrappers.append(f"""class {name}: public MockTexture<IDirect3D{kind}Texture9> {{
  void onDestroy() override;
{fields[0]}
public:
  using MockTexture<IDirect3D{kind}Texture9>::MockTexture;
{cancellations[0]}
}};
""")
        create = function(device, f"HRESULT Direct3DDevice9Ex_LSS<EnableSync>::Create{kind}Texture(")
        if negative_control == kind.lower():
            # Restore the original early return, leaving the wrapper uncollected.
            marker = "  // NV-DXVK start: Failed creation returns a null output and releases its client wrapper."
            if create.count(marker) != 1:
                raise ValueError(f"Cannot restore the original {kind} failure path")
            _, _, body_end, _ = function_bounds(create, f"HRESULT Direct3DDevice9Ex_LSS<EnableSync>::Create{kind}Texture(")
            create = create[:create.index(marker)] + (
                f'  WAIT_FOR_OPTIONAL_CREATE_FUNCTION_SERVER_RESPONSE("Create{kind}Texture()", '
                "D3DERR_INVALIDCALL, currentUID);\n}") + create[body_end:]
        methods.append("template<bool EnableSync>\n" + create)
        methods.append(function(implementation, f"void {name}::onDestroy()"))
    macros = (source / "bridge/src/util/util_bridgecommand.h").read_text(encoding="utf-8")
    macros = macros[macros.index("#define WAIT_FOR_SERVER_RESPONSE("):macros.index("using namespace bridge_util;")]
    output.mkdir(parents=True, exist_ok=True)
    (output / "texture_creation_wrappers.h").write_text(notices + "\n".join(wrappers), encoding="utf-8", newline="\n")
    (output / "texture_creation_methods.h").write_text(notices + macros + "\n".join(methods), encoding="utf-8", newline="\n")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--negative-control", choices=("volume", "cube"))
    args = parser.parse_args()
    prepare(args.source, args.output, args.negative_control)
